import{_ as r,C as s,o as e,c as o,j as d,a as n,E as i,a3 as l}from"./chunks/framework.D4-ViStF.js";const m=JSON.parse('{"title":"体用生克篇之五：观物洞玄歌","description":"从歌诀、起卦到屋宅与器物，练习将体用之理落在具体情境。","frontmatter":{"title":"体用生克篇之五：观物洞玄歌","description":"从歌诀、起卦到屋宅与器物，练习将体用之理落在具体情境。","category":"学习计划 · 第二阶段"},"headers":[],"relativePath":"yijing/meihua-yishu/ti-yong-sheng-ke/observing-things-song.md","filePath":"yijing/meihua-yishu/ti-yong-sheng-ke/observing-things-song.md","lastUpdated":1787730063000}'),p={name:"yijing/meihua-yishu/ti-yong-sheng-ke/observing-things-song.md"};function g(h,t,b,c,u,q){const a=s("DaoTextReading");return e(),o("div",null,[t[0]||(t[0]=d("h1",{id:"【体用生克篇之五】观物洞玄歌·起卦加数例·屋宅占诀·器物占",tabindex:"-1"},[n("【体用生克篇之五】观物洞玄歌·起卦加数例·屋宅占诀·器物占 "),d("a",{class:"header-anchor",href:"#【体用生克篇之五】观物洞玄歌·起卦加数例·屋宅占诀·器物占","aria-label":'Permalink to "【体用生克篇之五】观物洞玄歌·起卦加数例·屋宅占诀·器物占"'},"​")],-1)),t[1]||(t[1]=d("blockquote",null,[d("p",null,"本篇是体用生克篇的收官。从歌诀到案例到器物，将前四篇的理论落地到最具体的生活场景。")],-1)),t[2]||(t[2]=d("h2",{id:"📜-原文",tabindex:"-1"},[n("📜 原文 "),d("a",{class:"header-anchor",href:"#📜-原文","aria-label":'Permalink to "📜 原文"'},"​")],-1)),i(a,{colophon:"观物洞玄歌 · 屋宅器物占",tone:"ink",sections:[{id:"sec-01",label:"观物洞玄歌",showLabel:!0,sentences:[["洞玄歌者，洞达玄妙之说也。"],["此歌多为占宅气而发。"],["昔牛思晦尝入人家，知其吉凶先兆，盖此术云。"],["是故家之兴衰必有",{text:"祯祥妖孽",glossary:"g01"},"之",{text:"谶",glossary:"g02"},"，识者鉴之，不识者昧之。"],["故此歌发其",{text:"蕴奥",glossary:"g03"},"，皆理之必然者，切勿以浅近目之也。"],["世问万事无非数，理在其中，吉凶悔吝有其机，祸福可先知。"],["其五行，金、木、水、火、土，生克先为主；青、黄、赤、黑、白五形辨，察要分明。"],["人家吉凶何堪见？"],["只向玄中判。"],["入门辨察见闻时，于此察兴衰。"],["若还宅气如春意，家室生和气。"],["若然冷落似秋时，从此渐衰微。"],["自然馨香如兰室，福至无虚日。"],["鸡",{text:"豚",glossary:"g04"},"猫犬",{text:"秽熏猩",glossary:"g05"},"，贫病至相侵。"],["男妆女饰皆齐整，此去门风盛。"],["家人垢面与蓬头，定见有悲忧。"],["鬼啼妇叹",{text:"情怀悄",glossary:"g07"},"，祸害道阴小。"],["老人无故泣双垂，不日见愁悲。"],["门前墙壁缺，家道中渐歇。"],[{text:"溜漕",glossary:"g08"},"水势向门流，财帛永难收。"],["忽然屋上生奇草，益荫人家好。"],["门户幽爽绝尘埃，必定出高才。"],["偶悬",{text:"破履",glossary:"g09"},"当门户，必有奴欺主。"],["常常破碎在边门，断不利家君。"],["遮门临井桃花艳，内有风情染。"],["屋前屋后有高桐，离别主人翁。"],["井边倘种高梨树，长有离乡土。"],["祠堂神主忽焚香，火厄恐相招。"],["檐前瓦片当门堕，诸事愁崩破。"],["若施破碗厕坑中，从此见贫穷。"],["白昼不宜灯在地，死者还相继。"],["公然鼠向日中来，不日耗资财。"],[{text:"牝鸡司晨",glossary:"g10"},"鸣咿啼，人眷有灾厄。"],["清晨鹊噪连声继，远行人将至。"],["蟒蛇偶尔入人家，人病见妖邪。"],["雀群争遂当门盛，口舌纷纷定。"],["偶然",{text:"鹏鸟",glossary:"g11"},"叫当门，人口有灾逢。"],["入门若见有群羊，家主病",{text:"瘟黄",glossary:"g12"},"。"],["舟船若安在平地，虽稳成",{text:"淹滞",glossary:"g13"},"。"],["他家树阴过墙来，多得横来财。"],["阶前石砌多残折，成事多衰灭。"],["入门茶果应声来，",{text:"中馈",glossary:"g14"},"主",{text:"冢财",glossary:"g15"},"。"],["三餐时候炊烟早，家道渐基好。"],["连宵宿火不成时，人散与财离。"],["千门万户难详备，理在吾心地。"],["斯文引路发先天，深奥入玄玄。"],["此《洞玄歌》与《灵应》，同出而小异。"],["彼篇多为占卜而诀，盖占卜之际，随所出所见，以为克应之兆。"],["此歌则不特为占卜之事，一时而入人家，有此事，必有此理。"],["盖多寓观察之宋也。"],["然有数端，人家可得警戒而趋避之，或可转祸为福。"],["偶不知所因而",{text:"宥于数中",glossary:"g16"},"，",{text:"俾",glossary:"g17"},"吾见之，则善恶不逃乎明鉴矣。"]]},{id:"sec-02",label:"起卦加数例",showLabel:!0,sentences:[["寅年十二月初一日午时，有数家起造，俱在邻市之间。"],["有三家以此年月日时求占于先生，若同一卦，则吉凶莫辨矣。"],["先生以各姓而加数，遂断之而皆验。"],["盖三家求占，有田姓者，王姓者，韩姓者。"],["若寅年三数、十二与一，共十六，加王姓四画，得二十数，去八一十六，得四，震为上卦；又加午时，七数，总二十七数，去三八二十四，得三，离为下卦。"],["二十七中去四六二十四，余三为初爻，得丰变震，互见兑、巽。"],["其田姓加以田字六画，得水风井，变升，互见离、兑；其韩姓加入二十一画之数，得益变中孚，互见艮、坤。"],["乃以各家之姓起数，随各家之卦断之也。"],["不特起屋之年月日时加姓也，凡",{text:"冠婚",glossary:"g20"},"及葬事皆加一姓可矣。"],["若婚姻，则男女大事，必加二姓可也。"],["极北之人无姓，亦必有名，不辨其字，则数声音。"],["又无名，则随所寓也。"]]},{id:"sec-03",label:"屋宅之占诀",showLabel:!0,sentences:[["寅年十二月初一日午时起屋者，其家田姓，其占水风井，变地风升，互见离、兑，巽木为体，用卦坎水生也，虽兑金克木，得有离火，火虽无气，终是制金。"],["然有兑金，酉年月日，亦当有损失之忧。"],["亥子水年月日，当有进益，或得水边之财，坎生体巽也。"],["寅卯年当大快意，比和之气也。"],["但家必多口舌之",{text:"聒",glossary:"g18"},"，亦为兑也。"],["木体近春。"],["喜逢坎水，此居必能发旺。"],["二十九年后，此屋当毁。"],["盖二十九年者，",{text:"全卦之成数",glossary:"g21"},"也。"],["若非有兑在中，虽再见二十九年，屋当无恙也。"],["同时王姓家起造，得雷火丰，变震，互见兑、巽。"],["震木为体，离为用卦。"],["兑为体之互，克体亦切。"],["虽得离火制兑金，亦不纯美。"],["用火泄体之气，破耗资财。"],["每遇火年月日，主见此事，或因妇人而有损失。"],["家中亦多女子是非。"],["亥子寅卯之年月，却主进益田财。"],["盖震木为体，虽不见坎，终是利水年。"],["生体之气，不见震巽，亦逢寅、卯，为",{text:"体卦得局",glossary:"g22"},"之时也。"],["凡有震有巽，寅卯与木之气运年月，此居必大得意。"],["亦主得长子之力，变重震也。"],["二十二年复为火所焚。"],["韩姓之居，得益变中孚。"],["巽体，互见艮、坤，变兑克本。"],["此居必有官讼，见于酉年月日。"],["申酉年连见病患，所喜用卦其震与巽体比和，当见寅卯年月后。"],["申酉年后凶。"],["三十一年之后，遇申酉年，此居当毁。"],["若非有兑，或有一坎，再三十一年，此居亦无恙也。"]]},{id:"sec-04",label:"器物占",showLabel:!0,sentences:[["大抵占器物，并不喜见兑卦，盖兑为毁折也。"],["若坎为体，则见兑无伤。"],["干卦为体亦无害。"],["其余卦体，逢兑不久即破。"],["木之器物，或震巽为体，见兑为用，必不禁耐用矣。"],["破器之日，必申酉与占卜之年月日也。"],["又畜养之物，又不宜干、兑克体。"],["种植之物，干、兑克体，必不成，即成，亦有",{text:"斧戕",glossary:"g19"},"之厄。"],["种植之物，宜见坎也。"],["又凡见器物，欲知其成毁，亦看卦体，无克者则久长。"],["体逢克则不久，视其器物之气数，可久者，以全卦之年数断之；不可久者，以月数断之；至速者，以日数断之也。"]]}],glossary:[{id:"g01",term:"祯祥妖孽",pinyin:"zhēn xiáng yāo niè",meaning:"吉祥之兆（祯祥）与凶恶之兆（妖孽）"},{id:"g02",term:"谶",pinyin:"chèn",meaning:"预兆，应验的预言"},{id:"g03",term:"蕴奥",pinyin:"yùn ào",meaning:"深藏的奥义"},{id:"g04",term:"豚",pinyin:"tún",meaning:"猪"},{id:"g05",term:"秽熏猩",pinyin:"huì xūn xīng",meaning:"臭气熏天，猩：腥臭之气"},{id:"g06",term:"垢面蓬头",pinyin:"gòu",meaning:"脏脸蓬乱头发，形容邋遢不整"},{id:"g07",term:"情怀悄",pinyin:"qiǎo",meaning:"悄：忧愁，情怀悄：心情悲愁"},{id:"g08",term:"溜漕",pinyin:"liù cáo",meaning:"屋檐排水槽"},{id:"g09",term:"破履",pinyin:"pò lǚ",meaning:"破旧的鞋子"},{id:"g10",term:"牝鸡司晨",pinyin:"pìn jī sī chén",meaning:"母鸡报晓，喻阴盛阳衰，家道失序"},{id:"g11",term:"鹏鸟",pinyin:"péng niǎo",meaning:"此处指鸱鸮（猫头鹰）一类不祥之鸟"},{id:"g12",term:"瘟黄",pinyin:"wēn huáng",meaning:"瘟病，黄疸，泛指重病"},{id:"g13",term:"淹滞",pinyin:"yān zhì",meaning:"停滞不前，事业受阻"},{id:"g14",term:"中馈",pinyin:"zhōng kuì",meaning:"主持家务的女主人"},{id:"g15",term:"冢财",pinyin:"zhǒng cái",meaning:"主财，掌管财务"},{id:"g16",term:"宥于数中",pinyin:"yòu",meaning:"被数所困，宥：宽容，此处引申为受困"},{id:"g17",term:"俾",pinyin:"bǐ",meaning:"使，令"},{id:"g18",term:"聒",pinyin:"guō",meaning:"嘈杂，口舌之聒：话多嘈杂"},{id:"g19",term:"斧戕",pinyin:"fǔ qiāng",meaning:"被斧砍伤，戕：伤害"},{id:"g20",term:"冠婚",pinyin:"guān hūn",meaning:"冠礼与婚礼，人生大事"},{id:"g21",term:"全卦之成数",pinyin:"—",meaning:"全卦各爻五行生成数之总和，用于推算年限"},{id:"g22",term:"体卦得局",pinyin:"—",meaning:"体卦所属五行当令得势，即旺相之时"}],"aria-label":"观物洞玄歌原文"}),t[3]||(t[3]=l("",146))])}const y=r(p,[["render",g]]);export{m as __pageData,y as default};
